import { Activity, ArrowLeft, ArrowRight, Calendar, Check, CheckCircle2, ChevronRight, CircleHelp, Download, FileText, Filter, HeartPulse, Info, Mail, MapPin, MessageCircle, MoreHorizontal, Paperclip, Pencil, Plus, Printer, Search, Send, ShieldCheck, SlidersHorizontal, Star, Stethoscope, Trash2, UserRound, UsersRound, Video, X } from 'lucide-react'
